def tokens_desc(text):
    s = text.lower()
    for ch in [":", "/", ".", ",", "\n", "\t", "(", ")", "[", "]", ";", "\"", "'"]:
        s = s.replace(ch, " ")
    return s.split()


def tokens_ident(text):
    s = text.lower()
