        "slt", "sltu", "lui", "auipc", "jal", "jalr",
        "beq", "bne", "blt", "bge", "bltu", "bgeu",
        "lb", "lh", "lw", "lbu", "lhu", "sb", "sh", "sw",
        "fence", "ecall", "ebreak"
    ]
    for t in toks:
        for m in mnems:
            if t == m:
                return m
    return ""


def instr_kind(design):
    m = instr_mnemonic(design)
    if m in ["lb", "lh", "lw", "lbu", "lhu"]:
        return "load"
    if m in ["sb", "sh", "sw"]:
        return "store"
    if m in ["beq", "bne", "blt", "bge", "bltu", "bgeu"]:
        return "branch"
    if m in ["jal", "jalr"]:
        return "jump"
    if m in ["ecall", "ebreak"]:
